@once
<style>
.dm-modal{position:fixed;inset:0;z-index:1080;display:none;align-items:center;justify-content:center;padding:12px;background:#11182799}.dm-modal.open{display:flex}.dm-dialog{width:min(660px,100%);height:min(760px,calc(100dvh - 24px));display:grid;grid-template-rows:auto 1fr auto;background:#fff;border-radius:18px;box-shadow:0 24px 60px #0004}.dm-head,.dm-compose{padding:14px 16px;border-bottom:1px solid #e5e7eb}.dm-compose{border-top:1px solid #e5e7eb;border-bottom:0}.dm-list{overflow:auto;padding:16px;display:grid;align-content:start;gap:10px;background:#fafafa}.dm-bubble{max-width:82%;padding:10px 12px;border:1px solid #e5e7eb;border-radius:14px;white-space:pre-wrap;overflow-wrap:anywhere}.dm-bubble.mine{margin-left:auto;background:var(--primary,#7B3A0F);color:#fff;border-color:transparent}.dm-bubble img{max-width:100%;margin-top:8px;border-radius:10px;display:block}.dm-time{font-size:11px;opacity:.72;margin-top:5px}.dm-row{display:flex;gap:8px}.dm-row textarea{flex:1;min-width:0;border:1px solid #d1d5db;border-radius:12px;padding:10px;font:inherit;resize:none}.dm-send,.dm-close,.dm-back{border:0;cursor:pointer}.dm-send{background:var(--primary,#7B3A0F);color:#fff;border-radius:12px;padding:10px 14px;font-weight:700}.dm-close{border-radius:50%;width:38px;height:38px}.dm-back{background:transparent;color:#4b5563;font-weight:700;padding:6px 0}.dm-quick{display:flex;overflow:auto;gap:7px;margin:8px 0}.dm-quick button{white-space:nowrap;border:1px solid #d1d5db;background:#fff;border-radius:999px;padding:6px 9px;font-size:12px;cursor:pointer}
</style>
<div class="dm-modal" id="deliveryMessageModal" aria-hidden="true"><section class="dm-dialog" role="dialog" aria-modal="true" aria-labelledby="deliveryMessageTitle"><header class="dm-head d-flex align-items-center gap-3"><div class="flex-grow-1"><strong id="deliveryMessageTitle">Delivery messages</strong><div class="small text-muted" id="deliveryMessageSubtitle"></div></div><button type="button" class="dm-close" aria-label="Close messages" data-dm-close><i class="bi bi-x-lg"></i></button></header><div class="dm-list" id="deliveryMessageList" aria-live="polite"></div><form class="dm-compose" id="deliveryMessageForm" enctype="multipart/form-data"><div class="dm-quick"><button type="button">I’m available to receive the order.</button><button type="button">Please call when you arrive.</button><button type="button">I’m at the delivery location.</button><button type="button">Thank you.</button></div><div class="small text-danger" id="deliveryMessageError" role="alert"></div><div class="dm-row"><label class="btn btn-light mb-0" title="Attach image"><i class="bi bi-image"></i><input class="d-none" type="file" accept="image/jpeg,image/png,image/webp" name="image"></label><textarea name="message" rows="2" maxlength="1000" placeholder="Write a message…" aria-label="Message"></textarea><button class="dm-send" type="submit">Send</button></div></form></section></div>
<script>
(()=>{const modal=document.getElementById('deliveryMessageModal'),list=document.getElementById('deliveryMessageList'),form=document.getElementById('deliveryMessageForm'),error=document.getElementById('deliveryMessageError'),sub=document.getElementById('deliveryMessageSubtitle');let current,trigger,timer;const csrf=@json(csrf_token()),close=()=>{modal.classList.remove('open');document.body.style.overflow='';clearInterval(timer);trigger?.focus()},bubble=m=>{const e=document.createElement('article');e.className='dm-bubble '+(m.sender_type===current.role?'mine':'');if(m.message){const x=document.createElement('div');x.textContent=m.message;e.append(x)}if(m.image_path){const i=document.createElement('img');i.src=m.image_path;i.alt='Attached image';e.append(i)}const t=document.createElement('div');t.className='dm-time';t.textContent=new Date(m.created_at).toLocaleString();e.append(t);return e},load=async()=>{const r=await fetch(current.index,{credentials:'same-origin',headers:{Accept:'application/json'}}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||d.error||'Conversation is unavailable.');list.replaceChildren(...(d.messages||[]).map(bubble));if(!d.messages?.length)list.innerHTML='<div class="text-muted small text-center py-4">No messages yet. Start the conversation.</div>';list.scrollTop=list.scrollHeight};document.addEventListener('click',async e=>{const b=e.target.closest('[data-delivery-message]');if(b){trigger=b;current={index:b.dataset.index,send:b.dataset.send,role:b.dataset.role};sub.textContent=b.dataset.label||'';modal.classList.add('open');document.body.style.overflow='hidden';list.textContent='Loading conversation…';try{await load();form.querySelector('textarea').focus();timer=setInterval(()=>load().catch(()=>{}),10000)}catch(x){error.textContent=x.message}return}if(e.target.closest('[data-dm-close]')||e.target===modal)close();const q=e.target.closest('.dm-quick button');if(q)form.querySelector('textarea').value=q.textContent.trim()});document.addEventListener('keydown',e=>{if(e.key==='Escape'&&modal.classList.contains('open'))close()});form.addEventListener('submit',async e=>{e.preventDefault();if(!current)return;const b=form.querySelector('[type=submit]');b.disabled=true;error.textContent='';try{const r=await fetch(current.send,{method:'POST',credentials:'same-origin',headers:{'X-CSRF-TOKEN':csrf,Accept:'application/json'},body:new FormData(form)}),d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.message||d.error||'Message could not be sent.');form.reset();await load()}catch(x){error.textContent=x.message}finally{b.disabled=false}});setTimeout(()=>{const hash=window.location.hash;const target=hash==='#delivery-message'?document.querySelector('#delivery-message [data-delivery-message]'):document.querySelector(hash+' [data-delivery-message]');target?.click()},0)})();
</script>
<script>
(() => {
  const moveToBody = () => {
    const modal = document.getElementById('deliveryMessageModal');
    if (modal && modal.parentElement !== document.body) document.body.appendChild(modal);
  };
  document.readyState === 'loading' ? document.addEventListener('DOMContentLoaded', moveToBody) : moveToBody();
})();
</script>
@endonce
